def parse_flags(raw: str) -> dict[str, str]:
    flags = {}
    for line in raw.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" in line:
            key, value = line.split("=", 1)
            flags[key.strip()] = value.strip()
    return flags

